# -*- coding: utf-8 -*-
"""Festival detail content (historical background, rituals, verified images).

All images are 960px Wikimedia Commons thumbs. Keyed by event name as seeded in `seed.py`.
Applied in `seed.py` right after the EVENTS are created so the detail columns are filled on every fresh seed.
"""

EVENT_DETAILS = {'Ganesh Chaturthi': {'historical_background': "Ganesh Chaturthi honours Ganesha, the elephant-headed god of beginnings, on the fourth day of the waxing moon in Bhadrapada. While domestic worship is centuries old, the grand public festival was popularised in Pune in 1893 by Lokmanya Tilak, who turned the neighbourhood idols into a mass movement uniting communities during the freedom struggle. Today it is Maharashtra's largest and most famous public festival.", 'cultural_significance': 'The festival celebrates Vinayaka as the remover of obstacles and the god of wisdom and new beginnings. Neighbourhood trusts (mandals) compete with ever-more-artistic idols and take the celebrations to streets, temporary pandals and finally the rivers.', 'rituals_traditions': 'Families install a murti, offer modak sweets, durva grass and heart-shaped red aarti (kombdi) for ten days, then carry the idol through the streets to a river or the sea for immersion (visarjan) on Anant Chaturdashi. Eco-friendly clay idols and seed-embedded murtis have been encouraged in recent years.', 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Eco_friendly_images_of_God_Ganesh_on_display_for_Ganesh_Chaturthi_celebrations.jpg/960px-Eco_friendly_images_of_God_Ganesh_on_display_for_Ganesh_Chaturthi_celebrations.jpg"]', 'state_name': 'Maharashtra', 'city_name': 'Pune', 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Eco_friendly_images_of_God_Ganesh_on_display_for_Ganesh_Chaturthi_celebrations.jpg/960px-Eco_friendly_images_of_God_Ganesh_on_display_for_Ganesh_Chaturthi_celebrations.jpg'}, 'Ambubachi Mela': {'historical_background': 'Ambubachi Mela is the annual four-day fertility festival of the Kamakhya Temple on Nilachal Hill, Guwahati — one of the most important Shakti shrines of India. It is held during the monsoon (June) and marks the annual period of menstruation of the goddess, an ancient Tantric observance.', 'cultural_significance': "One of the largest gatherings of the northeast, drawing lakhs of pilgrims and sadhus who arrive to take part in Tantric worship at the shrine. The festival reaffirms the earth's creative power and the deep-rooted Shakti tradition of Assam.", 'rituals_traditions': 'The sanctum stays closed for three days while the goddess is believed to rest; on the fourth day (Ambubachi day) the doors open and offerings of Gamari-wood priestly rites and kesar-mix prasad are distributed. Householders and sadhus fast and observe ritual purity through the days.', 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/2/25/Kamakhya_Temple%2C_Guwahati.jpg/960px-Kamakhya_Temple%2C_Guwahati.jpg"]', 'state_name': 'Assam', 'city_name': 'Guwahati', 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/25/Kamakhya_Temple%2C_Guwahati.jpg/960px-Kamakhya_Temple%2C_Guwahati.jpg'}, 'Durga Puja': {'historical_background': "Durga Puja is the five-day autumn worship of Goddess Durga, rooted in Bengal's late-medieval tradition of household 'boron' pujas and brought into the public square by the Babu rajas of Calcutta from the 18th century. Kolkata's creative pandal culture grows from that civic tradition, and in 2021 UNESCO inscribed 'Durga Puja in Kolkata' on the Representative List of Intangible Cultural Heritage.", 'cultural_significance': 'For Bengal, the festival is the great annual carnival: the city becomes a giant open-air gallery, ferries carry crowds across the rivers to visit pandals, and communities reunite. It is the most important social and artistic event of the Bengali year.', 'rituals_traditions': "The rites run from Shashti (the day of 'bodhon' — invocation) through Pushpanjali on Saptami-Ashtami to Sindur Khela on Dashami, when women smear vermilion on the goddess and on one another before the idols are carried for immersion. Dhak drums, dhoop and agnbanti offerings mark each day.", 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/Durga_Puja_Festival_-_Kolkata_October_2025.jpg/960px-Durga_Puja_Festival_-_Kolkata_October_2025.jpg"]', 'state_name': 'West Bengal', 'city_name': 'Kolkata', 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/Durga_Puja_Festival_-_Kolkata_October_2025.jpg/960px-Durga_Puja_Festival_-_Kolkata_October_2025.jpg'}, 'Navratri Garba Utsav': {'historical_background': "Navratri is the nine-night worship of the Goddess Amba observed across Gujarat before Dussehra. The garba is the devotional circle dance performed around a garbi — an earthen lamp shrine of the goddess — a tradition kept alive in villages and cities alike. In 2023 UNESCO inscribed 'Garba of Gujarat' on the List of Intangible Cultural Heritage.", 'cultural_significance': "The festival is a celebration of devotion, music and community. Gujarat's state festival regulation (the 'lathi' rules) govern street dancing in cities such as Ahmedabad, protecting the huge nightly crowds that gather in grounds across the state.", 'rituals_traditions': 'Nights are spent circling the goddess in swift dandiya and clap-clad garba steps to folk percussion. On the tenth day, the effigies of Ravana are burnt for Dussehra. Navaratri also sees shakhas and competitions of step-design and dress across communities.', 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Garba_Navratri_03.jpg/960px-Garba_Navratri_03.jpg"]', 'state_name': 'Gujarat', 'city_name': 'Ahmedabad', 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Garba_Navratri_03.jpg/960px-Garba_Navratri_03.jpg'}, 'Mysuru Dasara': {'historical_background': "Mysuru Dasara is the royal ten-day festival of the Wodeyar dynasty, whose celebration traditions reach back to the Vijayanagara period. It is Karnataka's state festival (the Nadahabba) and culminates with a grand procession on Vijayadashami.", 'cultural_significance': "The festival combines ritual, royalty and civic display: the Maharaja's golden howdah, mounted on the elephant Arjuna (Nadagiri), is the centrepiece of the Jamboo Savari. Lakhs watch the parade along the palace avenue and the torchlight parade, Yuva Dasara and music-dance events fill the grounds.", 'rituals_traditions': "Worship of the Chamundeshwari goddess of the hills, the royal court pageant, the decorated elephant, tableau floats, and the farewell 'Hasu' before the palace lights up each evening with the entire palace facade illuminated.", 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/4/45/Mysore_Dasara_procession.jpg/960px-Mysore_Dasara_procession.jpg", "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/Mysore_Palace_Morning.jpg/960px-Mysore_Palace_Morning.jpg"]', 'state_name': 'Karnataka', 'city_name': 'Mysuru', 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/45/Mysore_Dasara_procession.jpg/960px-Mysore_Dasara_procession.jpg'}, 'Dev Deepawali': {'historical_background': "Dev Deepawali — the festival of lights of the gods — is celebrated on Kartik Purnima, fifteen days after Diwali, when the ghats of the Ganga in Varanasi are believed to receive the returning divinity of light. It has grown since the 1990s into one of north India's most spectacular ritual displays.", 'cultural_significance': 'For Varanasi, the evening is the offering of the river: the whole city — householders, ghat trusts, temples and the Nagar Nigam — illuminates the steps of the Ganga with lakhs of oil lamps.', 'rituals_traditions': 'Lamps (diyas) are set afloat as Deep Daan, priests perform the Maha Ganga Aarti at the Dashashwamedh ghat, and firework phatakas echo along the river while chants rise from the ghats.', 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/6/62/Varanasi_2023_Dev_Deepawali_During_the_day_03.jpg/960px-Varanasi_2023_Dev_Deepawali_During_the_day_03.jpg", "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Ganga_Aarti_at_Varanasi_in_the_evening.jpg/960px-Ganga_Aarti_at_Varanasi_in_the_evening.jpg"]', 'state_name': 'Uttar Pradesh', 'city_name': 'Varanasi', 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/62/Varanasi_2023_Dev_Deepawali_During_the_day_03.jpg/960px-Varanasi_2023_Dev_Deepawali_During_the_day_03.jpg'}, 'Pushkar Camel Fair': {'historical_background': "The Pushkar fair is the great annual desert carnival of Rajasthan, timed to the Kartik Purnima full moon. For centuries Pushkar — home to the only Brahma temple of India — has hosted a livestock and trading fair that is now the continent's largest camel gathering.", 'cultural_significance': "The fair is a crossroads of Rajasthan's rural economy and culture: it is the biggest livestock market in the region, and its moustache contests, fire dances, folk musicians and balloon rides have made it a global tourist brand of Indian heritage.", 'rituals_traditions': "Cattle and camel traders bargain in the dunes, racing and 'camel beauty' competitions crown champions, and folk performers — Kalbelia dancers, langa and manganiyar singers — entertain the crowds through the festival days around the holy lake.", 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/Camels_of_Pushkar_Camel_Fair_%282015%29.jpg/960px-Camels_of_Pushkar_Camel_Fair_%282015%29.jpg", "https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Rajasthani_folk_singer_at_Mehrangarh_fort.jpg/960px-Rajasthani_folk_singer_at_Mehrangarh_fort.jpg"]', 'state_name': 'Rajasthan', 'city_name': 'Pushkar', 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/Camels_of_Pushkar_Camel_Fair_%282015%29.jpg/960px-Camels_of_Pushkar_Camel_Fair_%282015%29.jpg'}, 'Hornbill Festival': {'historical_background': "The Hornbill Festival, known as the 'festival of festivals', is the multi-tribal winter celebration of the Naga people, inaugurated in 2000 and held each December at the Naga Heritage Village, Kisama, near Kohima in Nagaland.", 'cultural_significance': "It is one of India's most important celebrations of tribal culture, bringing together the sixteen major Naga tribes under one banner to stage their heritage, cuisine, crafts, songs and warrior traditions, and to showcase them to the world.", 'rituals_traditions': 'Days are filled with warrior games, morung (bachelor dormitory) traditions, Naga wrestling and folk dances of each tribe; evenings feature music concerts, while the bamboo-and-leaf heritage village itself — replicating Naga architecture — is the stage.', 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/Hornbill_Festival_Nagaland_01.jpg/960px-Hornbill_Festival_Nagaland_01.jpg", "https://upload.wikimedia.org/wikipedia/commons/thumb/6/63/Kabui_Dance.jpg/960px-Kabui_Dance.jpg"]', 'state_name': 'Nagaland', 'city_name': 'Kohima', 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/Hornbill_Festival_Nagaland_01.jpg/960px-Hornbill_Festival_Nagaland_01.jpg'}, 'Hemis Festival': {'historical_background': 'The Hemis Festival is the celebrated masked-dance (cham) festival of the Hemis Gompa near Leh, Ladakh, held on the tenth day of the fifth Tibetan month in honour of Padmasambhava (Guru Rinpoche), who carried Buddhism to the Himalaya.', 'cultural_significance': "It is among the largest Buddhist festivals of the northern Himalaya, drawing monks and laypeople from Ladakh and the wider Himalayan Buddhist world to the magnificent Hemis monastery, one of Ladakh's richest gompas.", 'rituals_traditions': 'Monks perform the ritual cham dances in brocade robes and masks, the monastery unveils the giant thangka (scroll painting) of Guru Rinpoche, and long trumpets and drums accompany the rites.', 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Hemis_Monastery_02.jpg/960px-Hemis_Monastery_02.jpg"]', 'state_name': 'Ladakh', 'city_name': 'Leh', 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Hemis_Monastery_02.jpg/960px-Hemis_Monastery_02.jpg'}, 'Rann Utsav': {'historical_background': "The Rann Utsav is the winter festival of the Great Rann of Kutch, the white salt desert of the Gujarat coast, held from early November through February. It transforms the remote marshland into India's largest desert camping and cultural festival.", 'cultural_significance': "The festival is a showcase of Kutch's renowned craft traditions — bandhani, leatherwork, embroidery and mirror-work — and brings the region's music, dance and artisans to the world stage.", 'rituals_traditions': "Guests stay in tented villages on the salt flats, take camel and cart safaris across the moonlit desert, watch folk dance and music evenings, and browse craft bazaars curated with the region's co-operatives.", 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/3/3c/White_salt_desert_at_Rann_of_Kutch.jpg/960px-White_salt_desert_at_Rann_of_Kutch.jpg"]', 'state_name': 'Gujarat', 'city_name': None, 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3c/White_salt_desert_at_Rann_of_Kutch.jpg/960px-White_salt_desert_at_Rann_of_Kutch.jpg'}, 'Pongal': {'historical_background': 'Pongal is the four-day Tamil harvest festival of the sun god, celebrated in mid-January at the start of the Tamil month Thai. Its observances reach back to the Sangam era and form the most important agrarian thanksgiving of the Tamil country.', 'cultural_significance': "'Thai' is the most auspicious month of the Tamil calendar, and Pongal — from the Tamil for 'boiling over' — is a festival of renewal, gratitude to the sun, the cattle and the land.", 'rituals_traditions': 'On Thai 1 the household cooks the sweet chakkarai pongal in a fresh clay pot as the sun rises and draws kolam patterns on the courtyard, then the family performs Mattu Pongal — decorating and worshipping the cattle — followed by the kaanum Pongal family outings and, in some regions, the Jallikattu bull-taming contest of Madurai and Salem.', 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/c/cc/A_man_dancing_with_fire_at_a_Pongal_Festival_in_Namakkal%2C_Tamil_Nadu%2C_India.jpg/960px-A_man_dancing_with_fire_at_a_Pongal_Festival_in_Namakkal%2C_Tamil_Nadu%2C_India.jpg"]', 'state_name': 'Tamil Nadu', 'city_name': 'Madurai', 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/cc/A_man_dancing_with_fire_at_a_Pongal_Festival_in_Namakkal%2C_Tamil_Nadu%2C_India.jpg/960px-A_man_dancing_with_fire_at_a_Pongal_Festival_in_Namakkal%2C_Tamil_Nadu%2C_India.jpg'}, 'Bihu': {'historical_background': 'Bihu is the principal festival of Assam, the great new-year and harvest observance of the Assamese year. Assam keeps three Bihus — Rongali (spring, Bohag), Kati (autumn) and Bhogali (winter, Magh); the festival celebrated in January is Magh Bihu, also called Bhogali (the feast Bihu).', 'cultural_significance': 'Bihu is at the heart of Assamese identity — its songs, dances and food bind the community at the close of the harvest. Schools, cultural clubs and the Assam government stage community Bihu rituals statewide.', 'rituals_traditions': "Bhogali Bihu is marked by the soaring of meji bonfires built in the fields, feasts of pitha, til-ladoo and the first of the season's new rice (bhog), and nights of Bihu dance and song around the community ground under the red-and-white Assamese gamosa.", 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/e/e8/Bihu_Dance_%2C_Festival_of_India.jpg/960px-Bihu_Dance_%2C_Festival_of_India.jpg"]', 'state_name': 'Assam', 'city_name': 'Guwahati', 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e8/Bihu_Dance_%2C_Festival_of_India.jpg/960px-Bihu_Dance_%2C_Festival_of_India.jpg'}, 'Sawai Gandharva Mahotsav': {'historical_background': "Founded in 1953 by the Arya Sangeet Prasarak Mandal of Pune, the Sawai Gandharva Mahotsav is the three-day festival Commemorating the teacher of Pandit Bhimsen Joshi — the celebrated vocalist Rambhau Kundgolkar, 'Sawai Gandharva'. Held each December, it has run without a break for more than seven decades.", 'cultural_significance': 'It is one of the most prestigious Hindustani classical music festivals of India, a platform on which maestros across gharanas perform and where young singers are heard alongside grande dames of the Kirana and other traditions.', 'rituals_traditions': "Across the three nights, the stage hosts solo vocal and instrumental concerts, the traditional celebration of the guru-shishya lineage is honoured, and the festival ends with the iconic full-house finale dedicated to Bhimsen Joshi's legacy.", 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Performance_of_Sarodiya_Brothers_at_SwarDarbar_Music_Concert.png/960px-Performance_of_Sarodiya_Brothers_at_SwarDarbar_Music_Concert.png"]', 'state_name': 'Maharashtra', 'city_name': 'Pune', 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Performance_of_Sarodiya_Brothers_at_SwarDarbar_Music_Concert.png/960px-Performance_of_Sarodiya_Brothers_at_SwarDarbar_Music_Concert.png'}, 'Kala Ghoda Arts Festival': {'historical_background': 'The Kala Ghoda Arts Festival is the annual open-air arts festival of the Kala Ghoda heritage precinct of South Mumbai, organised by the Kala Ghoda Association since 1999 around the iconic statue of King Edward VII.', 'cultural_significance': "It transforms the city's Victorian streets and covered spaces into a fortnight of visual art, dance, theatre, film, literature, food and heritage walks, inviting the whole city to engage with the arts in public.", 'rituals_traditions': 'Sculptures and installations line the footpaths, graffiti and craft stalls fill Rampart Row, heritage walks tour the Art Deco and Victorian architecture, and evenings close with music concerts and street performances.', 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/d/d6/Entrance_gate_to_Kala_Ghoda_Arts_Festival_2026.jpg/960px-Entrance_gate_to_Kala_Ghoda_Arts_Festival_2026.jpg"]', 'state_name': 'Maharashtra', 'city_name': 'Mumbai', 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d6/Entrance_gate_to_Kala_Ghoda_Arts_Festival_2026.jpg/960px-Entrance_gate_to_Kala_Ghoda_Arts_Festival_2026.jpg'}, 'Jaipur Literature Festival': {'historical_background': "Founded in 2006, the Jaipur Literature Festival is the world's largest free literature festival, held every January–February in the 300-year-old Diggi Palace grounds of Jaipur.", 'cultural_significance': "It gathers writers, poets, historians and thinkers from across the globe, presenting over two hundred sessions in English and Indian languages to tens of thousands of attendees — a defining cultural meeting place for the subcontinent's letters.", 'rituals_traditions': 'Public sessions and keynotes run through the day in the palace courtyards, book signings and debates on history, politics and poetry follow, and evenings bring music and spoken-word performances.', 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Gopalkrishna_Gandhi_at_Jaipur_Literature_Festival_2026_%288%29.jpg/960px-Gopalkrishna_Gandhi_at_Jaipur_Literature_Festival_2026_%288%29.jpg"]', 'state_name': 'Rajasthan', 'city_name': 'Jaipur', 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Gopalkrishna_Gandhi_at_Jaipur_Literature_Festival_2026_%288%29.jpg/960px-Gopalkrishna_Gandhi_at_Jaipur_Literature_Festival_2026_%288%29.jpg'}, 'Bastar Dussehra': {'historical_background': "Bastar Dussehra is the unique royal festival of the Bastar kingdom of Chhattisgarh, celebrated by the Gond and other tribal peoples. Unlike the pan-Indian Dussehra, Bastar's festival has no Ramayana plays — it centres on the deity Danteshwari Ma and is famous as the world's longest festival, observed over roughly seventy-five days.", 'cultural_significance': "The festival is the heart of Bastar's tribal identity and a rare living union of royal ritual and forest-community worship, drawn together in the largest tribal gathering of central India.", 'rituals_traditions': 'The rath — the wooden four-wheeled chariot of the goddess — is erected in Jagdalpur and pulled through the town, baital dances ring the palace, and the royal household performs the Sorni Jhumka aarti for Danteshwari, ending with the elaborate worship of the deity.', 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/8/81/Famous_Dussehra_Bastar_Jagdalpur_Chhattisgarh.jpg/960px-Famous_Dussehra_Bastar_Jagdalpur_Chhattisgarh.jpg"]', 'state_name': 'Chhattisgarh', 'city_name': 'Jagdalpur', 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/81/Famous_Dussehra_Bastar_Jagdalpur_Chhattisgarh.jpg/960px-Famous_Dussehra_Bastar_Jagdalpur_Chhattisgarh.jpg'}, 'Lohri': {'historical_background': 'Lohri is the Punjabi winter bonfire festival, celebrated on the night before Makar Sankranti (around 13 January) at the end of the winter solstice and the close of the rabi sowing. It is linked with the legend of Dulla Bhatti, the folk hero of the Punjab.', 'cultural_significance': "For Punjabis the night marks the turning of the season and the promise of the harvest; families and neighbourhoods gather to roast the season's reaped goods in the bonfire and greet the turn toward longer days.", 'rituals_traditions': "The family throws til, gur, peanuts and rewari into the bonfire, sings the Dulla Bhatti songs, and dances bhangra and giddha around the flames; in some households the festival celebrates a first-born son's arrival with communal treats.", 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/e/ed/Lohri_Festival_Ritual_from_Punjab.jpg/960px-Lohri_Festival_Ritual_from_Punjab.jpg"]', 'state_name': 'Punjab', 'city_name': None, 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/ed/Lohri_Festival_Ritual_from_Punjab.jpg/960px-Lohri_Festival_Ritual_from_Punjab.jpg'}, 'Onam': {'historical_background': "Onam is Kerala's harvest festival, celebrated in the Malayalam month of Chingam (August–September) with the legendary homecoming of the just King Mahabali — a tradition attested across a thousand years of Malayali memory.", 'cultural_significance': "It is the state festival of Kerala, a celebration of memory, equality and prosperity under the beloved king's annual return, observed by people of all communities.", 'rituals_traditions': 'Courtyards are spread with the pookalam flower carpet, the Vallam Kali (snake-boat) races run at Alappuzha, Pulikali tiger-dancers parade, and the family sits for the grand onam sadhya — the banana-leaf feast — wearing fresh onakodi garments.', 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/d/d6/Onam_Thriuvathira_Dance.jpg/960px-Onam_Thriuvathira_Dance.jpg"]', 'state_name': 'Kerala', 'city_name': 'Kochi', 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d6/Onam_Thriuvathira_Dance.jpg/960px-Onam_Thriuvathira_Dance.jpg'}, 'Thaipusam': {'historical_background': 'Thaipusam is the Tamil festival of the god Murugan (Kartikeya), celebrated on the full moon of the month Thai at the great hill shrines of Palani, Madurai and beyond — and carried to the Tamil diaspora around the world.', 'cultural_significance': 'It is a festival of vow and penance: devotees honour Murugan with the pal kudam (milk-pot) and the kavadi, the decorative shoulder-burden that walks the pilgrim to the hilltop shrine.', 'rituals_traditions': 'Processions of kavadi-bearers — often accompanied by music and in some traditions by piercings — climb the shrine ghats, milk offerings are poured at the sanctum, and the spirit of tapas-sadhana fills the festival grounds.', 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Thaipusam_celebration_with_kavadi_ceremony_at_Little_India.jpg/960px-Thaipusam_celebration_with_kavadi_ceremony_at_Little_India.jpg"]', 'state_name': 'Tamil Nadu', 'city_name': 'Madurai', 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Thaipusam_celebration_with_kavadi_ceremony_at_Little_India.jpg/960px-Thaipusam_celebration_with_kavadi_ceremony_at_Little_India.jpg'}, 'Mata Ki Chowki & Kumbh logistics': {'historical_background': "This 'logistics' festival grouping covers the interlinked congregations of the Kumbh cycle that turn the Triveni Sangam at Prayagraj into the largest gathering of humanity on earth. The Purna and Maha Kumbh are held on the 12- and 144-year cycles at the confluence of the Ganga, Yamuna and the mythical Saraswati.", 'cultural_significance': "The Kumbh is central to Hinduism's riverside pilgrimage tradition, attracting sadhus, akharas and lakhs of devotees over many months at the sangam.", 'rituals_traditions': 'The akharas stage the spectacular Shahi Snan (royal bath) processions at the auspicious bathing dates, devotees take the ritual dip and kalpavaas (long river-side austerity), and satsangs and havan fill the tent-cities of the fair.', 'gallery_images': '["https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/2019_Kumbh_Mela_-_People_in_Allahabad.jpg/960px-2019_Kumbh_Mela_-_People_in_Allahabad.jpg"]', 'state_name': 'Uttar Pradesh', 'city_name': 'Prayagraj', 'image_url': 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/2019_Kumbh_Mela_-_People_in_Allahabad.jpg/960px-2019_Kumbh_Mela_-_People_in_Allahabad.jpg'}}
